const { execSync } = require('child_process');

const repoUrl = $input.first().json.body.repoUrl;
try {
  const cmd = `mkdir -p /tmp/web-audit-platform && cd /tmp/web-audit-platform && rm -rf repo && git clone ${repoUrl} repo`;
  const stdout = execSync(cmd, { encoding: 'utf-8', stdio: 'pipe' });
  return [{ json: { repoUrl, success: true, stdout } }];
} catch (error) {
  throw new Error(`Failed to clone repository. Are you sure this is a public Git repo?`);
}

const { execSync } = require('child_process');

let vulnerabilities = 0;
let auditData = {};

try {
  const cmd = `find /tmp/web-audit-platform/repo -name "package.json" -not -path "*/node_modules/*" -exec dirname {} \\;`;
  const dirs = execSync(cmd, { encoding: 'utf-8' }).split('\n').filter(Boolean);

  for (const dir of dirs) {
    try {
      execSync(`cd "${dir}" && npm install --package-lock-only`, { stdio: 'ignore' });
      execSync(`cd "${dir}" && npm audit --json`, { encoding: 'utf-8', stdio: 'pipe' });
    } catch (err) {
      if (err.stdout) {
        try {
          const parsed = JSON.parse(err.stdout);
          vulnerabilities += parsed.metadata?.vulnerabilities?.critical || 0;
          auditData = parsed; // Keep the last one for reference
        } catch (e) {}
      }
    }
  }
} catch (error) {
}

const previousData = $input.first().json;
return [{ json: { ...previousData, auditOutput: auditData, critical_vulnerabilities: vulnerabilities } }];

const { execSync } = require('child_process');

let output;
try {
  const setupCmd = `cd /tmp/web-audit-platform/repo && npm install eslint@8 --no-save && echo '{"env":{"browser":true,"node":true,"es2021":true},"extends":"eslint:recommended","parserOptions":{"ecmaVersion":12,"sourceType":"module"},"rules":{"complexity":["error",10]}}' > .eslintrc.json`;
  execSync(setupCmd);
  const cmd = `cd /tmp/web-audit-platform/repo && npx eslint . --format json`;
  output = execSync(cmd, { encoding: 'utf-8' });
} catch (error) {
  output = error.stdout || '[]';
}

let complexityErrors = 0;
let eslintData = [];
try {
  eslintData = JSON.parse(output);
  complexityErrors = eslintData.reduce((acc, current) => acc + current.errorCount, 0);
} catch(e) {}

const previousData = $input.first().json;
return [{
  json: {
    ...previousData,
    complexityErrors: complexityErrors,
    eslintData: eslintData,
    scannedAt: new Date().toISOString()
  }
}];
